1	// app/Sources/GraphicStore.swift — one document's `graphics/` folder: where
2	// it is, what is in it, and when that changes (road map 10 §5f, G3a). It
3	// scans, hashes (G-13) and says what changed; a file edit is not undo (G-3).
4	//
5	// **Created on the app's first write, never at open** (spec §11 G-14):
6	// `ensureFolder()` is the one creator inside a package; while it is absent
7	// the PACKAGE directory is watched, so an outside `mkdir` is seen.
8	//
9	// **The watch** is G0's q7(c): a folder source raises `.write` only and an
10	// in-place (`O_TRUNC`) save raises nothing on the folder, so each module,
11	// font and asset file up to `fileSourceLimit`, modules first (spec §11
12	// G-19 (c), G-20 (a)), has its own source; events are coalesced over 100 ms.
13	// Every pass re-opens every source BY PATH (a save swaps inodes) and arms
14	// BEFORE it scans. A source whose `open` fails is a scan warning (G-20 (b)).
15	// An illegal asset name is warned and skipped; fonts are `+Fonts`' (G-23).
16	//
17	// **Threading.** One serial queue alone touches the queue-confined state; it
18	// diffs, and main publishes in order through `drain()`. Main waits on the
19	// queue only through `queue.sync`; the queue never waits on main.
20	
21	import CryptoKit
22	import Foundation
23	
24	extension Notification.Name {
25	    /// Posted on main (object: the store) when modules were added, changed
26	    /// or removed, or the font and asset set moved. `userInfo[namesKey]`:
27	    /// the names, sorted (all of them when the library moved — so EMPTY
28	    /// when it moved in a folder holding no module); `[libraryKey]`:
29	    /// whether it moved.
30	    static let graphicsDidChange = Notification.Name("FrameJobGraphicsDidChange")
31	
32	    /// Posted on main by a `GraphicStore` (object: the store) when the first
33	    /// save, or a Save As, moved its folder (`packageDidMove(to:)`).
34	    static let graphicsLocationDidChange = Notification.Name(
35	        "FrameJobGraphicsLocationDidChange")
36	}
37	
38	final class GraphicStore {
39	    static let folderName = "graphics", fontsFolderName = "fonts", assetsFolderName = "assets"
40	    static let namesKey = "names", libraryKey = "library"
41	    /// G-6: the faces the engine loads from `graphics/fonts/`.
42	    static let fontExtensions: Set<String> = ["ttf", "otf"]
43	    /// §5a: the pictures resvg draws from `graphics/assets/`.
44	    static let assetExtensions: Set<String> = ["png", "jpg", "jpeg", "gif", "webp", "svg", "svgz"]
45	    static let coalesceInterval: TimeInterval = 0.1
46	    /// The module, font and asset files one pass arms a source on: modules,
47	    /// then fonts, then assets, in listing order (spec §11 G-20 (a)).
48	    static let fileSourceLimit = 16
49	
50	    /// G-3's rule, `^[a-z0-9][a-z0-9-]{0,62}$`, mirrored from
51	    /// `model_graphic.rs`'s `check_name`; the core stays the validator.
52	    static func isModuleName(_ name: String) -> Bool {
53	        let scalars = Array(name.unicodeScalars)
54	        guard let head = scalars.first, scalars.count <= 63 else { return false }
55	        let lowerOrDigit = { (s: Unicode.Scalar) in
56	            ("a"..."z").contains(s) || ("0"..."9").contains(s)
57	        }
58	        return lowerOrDigit(head) && scalars.allSatisfy { lowerOrDigit($0) || $0 == "-" }
59	    }
60	
61	    private static let nameRule = "is not a module name (lowercase letters, digits and -, "
62	        + "starting with a letter or a digit, at most 63 characters)"
63	
64	    /// The core's own sentence for a bad name (`model_graphic.rs`).
65	    static func nameSentence(_ name: String) -> String {
66	        "graphic name \"\(name)\" \(nameRule)"
67	    }
68	
69	    static func hex<D: Digest>(_ digest: D) -> String {
70	        digest.map { String(format: "%02x", $0) }.joined()
71	    }
72	
73	    /// The app's bundled faces (`app/Resources/Fonts/`, G-6).
74	    let bundledFonts: URL
75	    /// The package, or nil for an untitled document.
76	    private(set) var package: URL?
77	    /// `<package>/graphics`, which the store creates only in
78	    /// `ensureFolder()`; or the untitled root, created at `start()`.
79	    private(set) var folderURL: URL
80	    /// The last published scan, written on main; locked because
81	    /// `module(named:)` and `makeLibrary()` may be called from any thread.
82	    private(set) var scan: GraphicScan {
83	        get { scanLock.withLock { storedScan } }
84	        set { scanLock.withLock { storedScan = newValue } }
85	    }
86	    /// Main; once per OBSERVED absent → present of `<package>/graphics`, made
87	    /// here or found. Never for the untitled root, never at `start()`.
88	    var folderDidAppear: (() -> Void)?
89	
90	    private var seed: URL?
91	    private let scanLock = NSLock()
92	    private var storedScan = GraphicScan.empty
93	    private let queue = DispatchQueue(label: "com.kgalligan.framejob.graphics")
94	
95	    private typealias Outcome = (
96	        scan: GraphicScan, names: [String], library: Bool, folderAppeared: Bool
97	    )
98	    // Queue-confined, all of it.
99	    private var generation = 0
100	    private var running = false
101	    private var sources: [DispatchSourceFileSystemObject] = []
102	    private var pending: DispatchWorkItem?
103	    private var lastScan = GraphicScan.empty
104	    private var folderPresent = false
105	    private var outbox: [Outcome] = []
106	    private var watchedPackage: URL?
107	    private var watchedFolder: URL
108	    var fontVerdicts: [String: GraphicFontVerdict] = [:]  // queue-confined; key: standardized path
109	
110	    /// `seed`: a folder whose entries are copied into the fresh untitled
111	    /// root at `start()` — an untitled document restored from autosave.
112	    init(package: URL?, seed: URL?, bundledFonts: URL) {
113	        let folder = package?.appendingPathComponent(Self.folderName, isDirectory: true)
114	            ?? URL(fileURLWithPath: NSTemporaryDirectory(), isDirectory: true)
115	            .appendingPathComponent("FrameJob", isDirectory: true)
116	            .appendingPathComponent(UUID().uuidString + "-graphics", isDirectory: true)
117	        self.package = package
118	        self.seed = package == nil ? seed : nil
119	        self.bundledFonts = bundledFonts
120	        folderURL = folder
121	        watchedFolder = folder
122	    }
123	
124	    deinit {
125	        // No `queue.sync`: the last release can come from a handler on the queue.
126	        for source in sources { source.cancel() }
127	    }
128	
129	    // MARK: - Life cycle (main)
130	
131	    func start() {
132	        let files = FileManager.default
133	        if package == nil {
134	            try? files.createDirectory(at: folderURL, withIntermediateDirectories: true)
135	            if let seed = seed, let entries = try? files.contentsOfDirectory(
136	                at: seed, includingPropertiesForKeys: nil)
137	            {
138	                for entry in entries {
139	                    try? files.copyItem(
140	                        at: entry, to: folderURL.appendingPathComponent(entry.lastPathComponent))
141	                }
142	            }
143	            seed = nil
144	        }
145	        if self.package != nil { writeManual() }
146	        let (package, folder) = (self.package, folderURL)
147	        let initial: GraphicScan = queue.sync {
148	            generation += 1
149	            running = true
150	            watchedPackage = package
151	            watchedFolder = folder
152	            let (found, exists) = armAndScan(generation)
153	            for (name, module) in found.modules {
154	                Self.dropKept(revision: module.revision, named: name, in: folder)
155	            }
156	            lastScan = found
157	            folderPresent = exists
158	            outbox = []
159	            return found
160	        }
161	        scan = initial
162	    }
163	
164	    func stop() {
165	        queue.sync {
166	            generation += 1
167	            running = false
168	            pending?.cancel()
169	            pending = nil
170	            cancelSources()
171	            outbox = []
172	        }
173	    }
174	
175	    func packageDidMove(to package: URL?) {
176	        guard let package = package else { return }
177	        let folder = package.appendingPathComponent(Self.folderName, isDirectory: true)
178	        guard folder.standardizedFileURL.path != folderURL.standardizedFileURL.path else { return }
179	        stop()
180	        removeScratchRoot()
181	        self.package = package
182	        folderURL = folder
183	        start()
184	        NotificationCenter.default.post(name: .graphicsLocationDidChange, object: self)
185	    }
186	
187	    func rescan() {
188	        queue.sync { pass(generation) }
189	        drain()
190	    }
191	
192	    /// Main only, never from the queue: `body` on the store's queue, so a
193	    /// file act of the app's (`removeModule`, `moveModule`) never interleaves
194	    /// with a pass.
195	    func onQueue<T>(_ body: () throws -> T) rethrows -> T {
196	        try queue.sync(execute: body)
197	    }
198	
199	    /// The ONE creator of `graphics/` inside a package (G-14).
200	    func ensureFolder() throws {
201	        guard !FileManager.default.fileExists(atPath: folderURL.path) else { return }
202	        try FileManager.default.createDirectory(at: folderURL, withIntermediateDirectories: true)
203	        writeManual()
204	        rescan()
205	    }
206	
207	    func module(named name: String) -> GraphicModuleFile? { scan.modules[name] }
208	
209	    /// A NEW builder each call — a library is frozen by its first compile
210	    /// or rasterize — holding the bundled faces, then `scan.fonts`, then
211	    /// `scan.assets` by name.
212	    func makeLibrary() throws -> GraphicLibrary { try makeIndexedLibrary().library }
213	
214	    /// The `.ttf` / `.otf` files in `folder`, sorted by name: the faces `makeLibrary()` adds first.
215	    static func bundledFontURLs(in folder: URL) -> [URL] {
216	        let all = (try? FileManager.default.contentsOfDirectory(
217	            at: folder, includingPropertiesForKeys: nil)) ?? []
218	        return all.sorted(by: { $0.lastPathComponent < $1.lastPathComponent })
219	            .filter { fontExtensions.contains($0.pathExtension.lowercased()) }
220	    }
221	
222	    /// `makeLibrary()`'s library with what each of its font blobs is — `fonts[i]` the project
223	    /// file blob `i` came from, nil for a bundled face — and the scan it was built from
224	    /// (`GraphicPackageJob`, spec §11 G-46 (b)).
225	    func makeIndexedLibrary() throws -> (
226	        library: GraphicLibrary, fonts: [GraphicFile?], scan: GraphicScan
227	    ) {
228	        let library = GraphicLibrary()
229	        var fonts: [GraphicFile?] = []
230	        for url in Self.bundledFontURLs(in: bundledFonts) {
231	            try library.addFont(Data(contentsOf: url))
232	            fonts.append(nil)
233	        }
234	        let current = scan
235	        for font in current.fonts {
236	            try library.addFont(font.bytes)
237	            fonts.append(font)
238	        }
239	        for asset in current.assets { try library.addAsset(name: asset.name, bytes: asset.bytes) }
240	        return (library, fonts, current)
241	    }
242	
243	    // MARK: - Publishing (main)
244	
245	    /// Takes the queue's outcomes and publishes each in order.
246	    private func drain() {
247	        let outcomes: [Outcome] = queue.sync { defer { outbox = [] }; return outbox }
248	        for outcome in outcomes {
249	            scan = outcome.scan
250	            if outcome.folderAppeared { folderDidAppear?() }
251	            guard !outcome.names.isEmpty || outcome.library else { continue }
252	            NotificationCenter.default.post(
253	                name: .graphicsDidChange, object: self,
254	                userInfo: [Self.namesKey: outcome.names, Self.libraryKey: outcome.library])
255	        }
256	    }
257	
258	    // MARK: - The queue
259	
260	    /// A source fired: the FIRST event schedules a pass 100 ms out, and the
261	    /// ones after it are absorbed into that pass.
262	    private func sourceFired(_ g: Int) {
263	        guard running, generation == g, pending == nil else { return }
264	        let item = DispatchWorkItem { [weak self] in
265	            guard let self = self, self.running, self.generation == g else { return }
266	            self.pending = nil
267	            self.pass(g)
268	            DispatchQueue.main.async { [weak self] in self?.drain() }
269	        }
270	        pending = item
271	        queue.asyncAfter(deadline: .now() + Self.coalesceInterval, execute: item)
272	    }
273	
274	    /// Re-arms, rescans and diffs against the last pass; the outcome goes to
275	    /// the outbox for `drain()`.
276	    private func pass(_ g: Int) {
277	        guard running, generation == g else { return }
278	        let (found, exists) = armAndScan(g)
279	        var names = Set<String>()
280	        for (name, module) in found.modules
281	        where lastScan.modules[name]?.revision != module.revision {
282	            names.insert(name)
283	        }
284	        for name in lastScan.modules.keys where found.modules[name] == nil { names.insert(name) }
285	        let library = found.libraryVersion != lastScan.libraryVersion
286	        if library { names.formUnion(found.modules.keys) }
287	        let appeared = watchedPackage != nil && !folderPresent && exists
288	        Self.keepReplaced(from: lastScan, to: found, in: watchedFolder)
289	        lastScan = found
290	        folderPresent = exists
291	        outbox.append((found, names.sorted(), library, appeared))
292	    }
293	
294	    private func cancelSources() {
295	        for source in sources { source.cancel() }
296	        sources = []
297	    }
298	
299	    /// FOLDER mode when the folder exists (a source on it, on each existing
300	    /// subfolder, and on the first `fileSourceLimit` module, font and asset
301	    /// files); PACKAGE mode when a saved package has none (one source on the
302	    /// package directory). An untitled root found absent is recreated. Arms
303	    /// first, then scans; a source that did not arm is a warning.
304	    private func armAndScan(_ g: Int) -> (GraphicScan, Bool) {
305	        cancelSources()
306	        let files = FileManager.default
307	        var exists = files.fileExists(atPath: watchedFolder.path)
308	        if !exists, watchedPackage == nil {
309	            try? files.createDirectory(at: watchedFolder, withIntermediateDirectories: true)
310	            exists = files.fileExists(atPath: watchedFolder.path)
311	        }
312	        guard exists else {
313	            let unwatched = watchedPackage.flatMap { arm($0, folder: true, g) }
314	            return (.empty(warnings: unwatched.map { [$0] } ?? []), false)
315	        }
316	        var warnings: [String] = []
317	        let fonts = watchedFolder.appendingPathComponent(Self.fontsFolderName, isDirectory: true)
318	        let assets = watchedFolder.appendingPathComponent(Self.assetsFolderName, isDirectory: true)
319	        for folder in [watchedFolder, fonts, assets] where files.fileExists(atPath: folder.path) {
320	            if let unwatched = arm(folder, folder: true, g) { warnings.append(unwatched) }
321	        }
322	        var moduleURLs: [URL] = []
323	        for url in listing(watchedFolder) where url.pathExtension == "js" {
324	            guard Self.isModuleName(url.deletingPathExtension().lastPathComponent) else {
325	                warnings.append("\(Self.folderName)/\(url.lastPathComponent) \(Self.nameRule)")
326	                continue
327	            }
328	            moduleURLs.append(url)
329	        }
330	        let fontURLs = listing(fonts).filter {
331	            Self.fontExtensions.contains($0.pathExtension.lowercased())
332	        }
333	        var assetURLs: [URL] = []
334	        for url in listing(assets)
335	        where Self.assetExtensions.contains(url.pathExtension.lowercased()) {
336	            guard GraphicAssetName.isLegal(url.lastPathComponent) else {
337	                warnings.append("\(Self.relative(url)) \(GraphicAssetName.rule) and was skipped")
338	                continue
339	            }
340	            assetURLs.append(url)
341	        }
342	        for url in (moduleURLs + fontURLs + assetURLs).prefix(Self.fileSourceLimit) {
343	            if let unwatched = arm(url, folder: false, g) { warnings.append(unwatched) }
344	        }
345	        var modules: [String: GraphicModuleFile] = [:]
346	        for url in moduleURLs {
347	            let name = url.deletingPathExtension().lastPathComponent
348	            guard let bytes = try? Data(contentsOf: url) else { continue }
349	            modules[name] = GraphicModuleFile(
350	                name: name, url: url, bytes: bytes, revision: Self.hex(SHA256.hash(data: bytes)))
351	        }
352	        let (fontFiles, fontWarnings) = validatedFonts(fontURLs)
353	        warnings += fontWarnings
354	        var assetFiles: [GraphicFile] = []
355	        for url in assetURLs {
356	            guard let bytes = try? Data(contentsOf: url) else { continue }
357	            // An empty `Data` crosses the FFI as NULL, which `addAsset` refuses.
358	            guard !bytes.isEmpty else {
359	                warnings.append("\(Self.relative(url)) is empty and was skipped")
360	                continue
361	            }
362	            assetFiles.append(GraphicFile(name: url.lastPathComponent, url: url, bytes: bytes))
363	        }
364	        var hasher = SHA256()
365	        for file in fontFiles + assetFiles {
366	            hasher.update(data: Data(file.name.utf8))
367	            hasher.update(data: file.bytes)
368	        }
369	        let found = GraphicScan(
370	            modules: modules, fonts: fontFiles, assets: assetFiles,
371	            libraryVersion: Self.hex(hasher.finalize()), warnings: warnings)
372	        return (found, true)
373	    }
374	
375	    /// `graphics/fonts/x.ttf` for a warning.
376	    static func relative(_ url: URL) -> String {
377	        let parent = url.deletingLastPathComponent().lastPathComponent
378	        return "\(folderName)/\(parent)/\(url.lastPathComponent)"
379	    }
380	
381	    /// A folder's regular files, sorted by name; empty when it is absent.
382	    private func listing(_ folder: URL) -> [URL] {
383	        let entries = (try? FileManager.default.contentsOfDirectory(
384	            at: folder, includingPropertiesForKeys: [.isRegularFileKey],
385	            options: [.skipsHiddenFiles])) ?? []
386	        let regular = entries.filter {
387	            (try? $0.resourceValues(forKeys: [.isRegularFileKey]))?.isRegularFile == true
388	        }
389	        return regular.sorted { $0.lastPathComponent < $1.lastPathComponent }
390	    }
391	
392	    /// Arms one source; nil when it is armed, else the scan warning saying
393	    /// what is not watched and why (spec §11 G-20 (b)).
394	    private func arm(_ url: URL, folder: Bool, _ g: Int) -> String? {
395	        let descriptor = open(url.path, O_EVTONLY)
396	        guard descriptor >= 0 else {
397	            let code = errno
398	            let why = String(cString: strerror(code))
399	            return "\(watchSubject(url, folder: folder)) is not watched: open failed (\(why))"
400	        }
401	        let mask: DispatchSource.FileSystemEvent = folder
402	            ? [.write, .delete, .rename, .revoke] : [.write, .extend, .delete, .rename]
403	        let source = DispatchSource.makeFileSystemObjectSource(
404	            fileDescriptor: descriptor, eventMask: mask, queue: queue)
405	        source.setEventHandler { [weak self] in self?.sourceFired(g) }
406	        source.setCancelHandler { close(descriptor) }
407	        source.resume()
408	        sources.append(source)
409	        return nil
410	    }
411	
412	    /// `graphics/`, `graphics/fonts/`, `graphics/assets/`, `graphics/<file>`,
413	    /// `graphics/fonts/<file>`, `graphics/assets/<file>` or `the package`, for a warning.
414	    private func watchSubject(_ url: URL, folder: Bool) -> String {
415	        if url == watchedPackage { return "the package" }
416	        if url == watchedFolder { return "\(Self.folderName)/" }
417	        if folder { return "\(Self.folderName)/\(url.lastPathComponent)/" }
418	        let parent = url.deletingLastPathComponent().standardizedFileURL.path
419	        return parent == watchedFolder.standardizedFileURL.path
420	            ? "\(Self.folderName)/\(url.lastPathComponent)" : Self.relative(url)
421	    }
422	}
