1	// app/Sources/GraphicStore+History.swift — the kept revisions of a
2	// document's modules and the rename journal (spec §11 G-27, G-28, G-29).
3	//
4	// **On disk**, inside `graphics/`:
5	// `history/<name>/<%06d sequence>-<revision>.js` is one kept text — the next
6	// sequence is the highest plus one, and any other file there is ignored —
7	// and `history/renames.json` is a JSON array of `[a, b]` pairs (the app
8	// moved the file FROM `a` TO `b`; the repair only ever moves it back, G-28
9	// (e)), oldest first, at most `renameJournalLimit`, a repeated unordered
10	// pair moved to the end. Both are user content carried by every save (spec
11	// §5.6), never a cache.
12	//
13	// **`history/` is created only inside an existing `graphics/`** (G-14:
14	// `ensureFolder()` stays the one creator of the folder), with no
15	// `packageContentsDidChangeOnDisk()` call — `fonts/`'s precedent in
16	// `GraphicStore+Import.swift`.
17	//
18	// **History never holds the current text.** `keepReplaced`, which a pass
19	// calls on the store's queue before it stores its scan, keeps the bytes a
20	// module's new text replaced and drops the new text's own revision; a
21	// text kept twice is listed once, and the lowest sequences past
22	// `historyLimit` are pruned. Nothing is kept at `start()`, for a removal
23	// the app did not make, or for a text that came and went inside one pass;
24	// `start()` DROPS each module's current revision from its history (a text
25	// put back while the project was closed), which is a drop and not a keep.
26	//
27	// **A file-less name with kept revisions is a DELETED module** (G-27 (f);
28	// a rename killed part-way leaves the same state: G-28 (f)): `moveHistory`
29	// leaves no `history/<from>/` behind, which is what makes that test sound
30	// for `ProjectDocument.reconcileGraphicNames()`.
31	
32	import CryptoKit
33	import Foundation
34	
35	/// One kept text of a module: its revision (G-13), its place in the
36	/// module's history and its file.
37	struct GraphicKept: Equatable {
38	    let revision: String, sequence: Int, url: URL
39	}
40	
41	extension GraphicStore {
42	    static let historyFolderName = "history", renameJournalName = "renames.json"
43	    static let historyLimit = 10, renameJournalLimit = 32
44	
45	    // MARK: - Reading (main)
46	
47	    /// The kept texts of `name`, newest first, read from the disk; empty
48	    /// for a name that is not a module name.
49	    func kept(named name: String) -> [GraphicKept] {
50	        Array(Self.keptEntries(named: name, in: folderURL).reversed())
51	    }
52	
53	    /// The names holding at least one kept text, sorted — deleted modules
54	    /// included.
55	    func keptNames() -> [String] {
56	        let history = folderURL.appendingPathComponent(Self.historyFolderName, isDirectory: true)
57	        let names = (try? FileManager.default.contentsOfDirectory(atPath: history.path)) ?? []
58	        return names.filter { !Self.keptEntries(named: $0, in: folderURL).isEmpty }.sorted()
59	    }
60	
61	    /// The journalled renames, newest first.
62	    func renamePairs() -> [(String, String)] {
63	        Self.journal(in: folderURL).reversed().map { ($0[0], $0[1]) }
64	    }
65	
66	    // MARK: - Writing (the store's queue, or main inside `onQueue`)
67	
68	    /// Keeps `bytes` as the newest text of `name`: an entry already holding
69	    /// that revision is removed first, then the lowest sequences past
70	    /// `historyLimit` are pruned. Nothing unless `folder` exists.
71	    static func keep(_ bytes: Data, named name: String, in folder: URL) {
72	        let files = FileManager.default
73	        guard isModuleName(name), files.fileExists(atPath: folder.path) else { return }
74	        let directory = historyDirectory(of: name, in: folder)
75	        try? files.createDirectory(at: directory, withIntermediateDirectories: true)
76	        let revision = hex(SHA256.hash(data: bytes))
77	        let entries = keptEntries(named: name, in: folder)
78	        let next = (entries.last?.sequence ?? 0) + 1
79	        do {
80	            try bytes.write(
81	                to: directory.appendingPathComponent(entryName(next, revision)), options: .atomic)
82	        } catch {
83	            return
84	        }
85	        tidy(name, in: folder)
86	    }
87	
88	    /// Removes every kept entry of `name` holding `revision`.
89	    static func dropKept(revision: String, named name: String, in folder: URL) {
90	        for entry in keptEntries(named: name, in: folder) where entry.revision == revision {
91	            try? FileManager.default.removeItem(at: entry.url)
92	        }
93	        removeIfEmpty(historyDirectory(of: name, in: folder))
94	    }
95	
96	    /// One pass's history work, file work only: for every name in BOTH
97	    /// scans whose revision differs, the old scan's bytes are kept; for
98	    /// every name whose revision is new or changed, the current revision is
99	    /// dropped from its history.
100	    static func keepReplaced(from last: GraphicScan, to found: GraphicScan, in folder: URL) {
101	        for (name, module) in found.modules.sorted(by: { $0.key < $1.key }) {
102	            let old = last.modules[name]
103	            guard old?.revision != module.revision else { continue }
104	            if let old = old { keep(old.bytes, named: name, in: folder) }
105	            dropKept(revision: module.revision, named: name, in: folder)
106	        }
107	    }
108	
109	    /// `from`'s entries appended, in order, after `to`'s highest sequence,
110	    /// then pruned; `history/<from>/` is gone afterwards. A throw leaves
111	    /// both histories as they were.
112	    static func moveHistory(from: String, to: String, in folder: URL) throws {
113	        let files = FileManager.default
114	        let source = historyDirectory(of: from, in: folder)
115	        guard files.fileExists(atPath: source.path) else { return }
116	        let target = historyDirectory(of: to, in: folder)
117	        guard files.fileExists(atPath: target.path) else {
118	            try files.moveItem(at: source, to: target)
119	            return
120	        }
121	        var sequence = keptEntries(named: to, in: folder).last?.sequence ?? 0
122	        var moved: [(from: URL, to: URL)] = []
123	        do {
124	            for entry in keptEntries(named: from, in: folder) {
125	                sequence += 1
126	                let landed = target.appendingPathComponent(entryName(sequence, entry.revision))
127	                try files.moveItem(at: entry.url, to: landed)
128	                moved.append((entry.url, landed))
129	            }
130	            try files.removeItem(at: source)
131	        } catch {
132	            for pair in moved.reversed() { try? files.moveItem(at: pair.to, to: pair.from) }
133	            throw error
134	        }
135	        tidy(to, in: folder)
136	    }
137	
138	    /// Journals a rename: the pair appended, an earlier entry of the same
139	    /// unordered pair removed, the oldest dropped past `renameJournalLimit`.
140	    /// Nothing unless `folder` exists.
141	    static func recordRename(_ a: String, _ b: String, in folder: URL) {
142	        let files = FileManager.default
143	        guard files.fileExists(atPath: folder.path) else { return }
144	        var pairs = journal(in: folder).filter { Set($0) != Set([a, b]) }
145	        pairs.append([a, b])
146	        pairs = Array(pairs.suffix(renameJournalLimit))
147	        let history = folder.appendingPathComponent(historyFolderName, isDirectory: true)
148	        try? files.createDirectory(at: history, withIntermediateDirectories: true)
149	        guard let data = try? JSONSerialization.data(withJSONObject: pairs) else { return }
150	        try? data.write(to: renameJournalURL(in: folder), options: .atomic)
151	    }
152	
153	    /// `history/renames.json` as it is on disk: its bytes, or nil when
154	    /// there is no file.
155	    static func renameJournalBytes(in folder: URL) -> Data? {
156	        try? Data(contentsOf: renameJournalURL(in: folder))
157	    }
158	
159	    /// Puts the journal back as `renameJournalBytes` read it: those bytes,
160	    /// or no file — what a rename refused after its pair was written does,
161	    /// at the fold (`moveModule`) or at the clips (`renameGraphic`'s move
162	    /// back), so a refused act journals nothing (G-28 (d)).
163	    static func putBackRenameJournal(_ bytes: Data?, in folder: URL) {
164	        let url = renameJournalURL(in: folder)
165	        if let bytes = bytes {
166	            try? bytes.write(to: url, options: .atomic)
167	        } else {
168	            try? FileManager.default.removeItem(at: url)
169	        }
170	    }
171	
172	    // MARK: - The files
173	
174	    private static func renameJournalURL(in folder: URL) -> URL {
175	        folder.appendingPathComponent(historyFolderName, isDirectory: true)
176	            .appendingPathComponent(renameJournalName)
177	    }
178	
179	    /// `history/<name>/` inside `folder`.
180	    static func historyDirectory(of name: String, in folder: URL) -> URL {
181	        folder.appendingPathComponent(historyFolderName, isDirectory: true)
182	            .appendingPathComponent(name, isDirectory: true)
183	    }
184	
185	    private static func entryName(_ sequence: Int, _ revision: String) -> String {
186	        String(format: "%06d", sequence) + "-" + revision + ".js"
187	    }
188	
189	    /// The kept entries of `name`, oldest first: every
190	    /// `<sequence>-<64 hex digits>.js` in its directory.
191	    private static func keptEntries(named name: String, in folder: URL) -> [GraphicKept] {
192	        guard isModuleName(name) else { return [] }
193	        let directory = historyDirectory(of: name, in: folder)
194	        let names = (try? FileManager.default.contentsOfDirectory(atPath: directory.path)) ?? []
195	        var entries: [GraphicKept] = []
196	        for file in names where file.hasSuffix(".js") {
197	            let parts = file.dropLast(3).split(separator: "-", omittingEmptySubsequences: false)
198	            guard parts.count == 2, let sequence = Int(parts[0]), sequence > 0,
199	                parts[1].count == 64, parts[1].allSatisfy({ "0123456789abcdef".contains($0) })
200	            else { continue }
201	            entries.append(GraphicKept(
202	                revision: String(parts[1]), sequence: sequence,
203	                url: directory.appendingPathComponent(file)))
204	        }
205	        return entries.sorted { $0.sequence < $1.sequence }
206	    }
207	
208	    /// One revision once (its highest sequence), then at most
209	    /// `historyLimit` entries, the lowest sequences removed.
210	    private static func tidy(_ name: String, in folder: URL) {
211	        let files = FileManager.default
212	        var seen = Set<String>()
213	        var newestFirst: [GraphicKept] = []
214	        for entry in keptEntries(named: name, in: folder).reversed() {
215	            if seen.insert(entry.revision).inserted {
216	                newestFirst.append(entry)
217	            } else {
218	                try? files.removeItem(at: entry.url)
219	            }
220	        }
221	        for entry in newestFirst.dropFirst(historyLimit) { try? files.removeItem(at: entry.url) }
222	    }
223	
224	    private static func removeIfEmpty(_ directory: URL) {
225	        let files = FileManager.default
226	        guard let names = try? files.contentsOfDirectory(atPath: directory.path), names.isEmpty
227	        else { return }
228	        try? files.removeItem(at: directory)
229	    }
230	
231	    /// The journal as written: every element that is a pair of strings.
232	    private static func journal(in folder: URL) -> [[String]] {
233	        guard let data = renameJournalBytes(in: folder),
234	            let pairs = try? JSONSerialization.jsonObject(with: data) as? [Any]
235	        else { return [] }
236	        return pairs.compactMap { $0 as? [String] }.filter { $0.count == 2 }
237	    }
238	}
