1	// app/Sources/ProjectDocument+GraphicFiles.swift — deleting, renaming and
2	// restoring a module of the document's `graphics/` (spec §11 G-27, G-28,
3	// G-29; issue #103): the three bodies BOTH doors call — the agent's
4	// `delete_graphic`, `rename_graphic` and `restore_graphic`
5	// (`AgentServer+GraphicFiles.swift`) and File ▸ Delete Graphic…, Rename
6	// Graphic… and Restore Graphic Version… — so the two refuse in the same
7	// sentences, and the repair that keeps a clip's module name and the file
8	// together across Undo.
9	//
10	// **Every throw of a body's own is a `ReelCoreError`**, its message the
11	// sentence. The "used" and "drawn" refusals are written here and are not a
12	// core rule's: each names a file act's precondition.
13	//
14	// **A file act is not an undo step and never dirties the document** (G-3):
15	// only a rename's `set_graphic` ops are model state, applied through the
16	// caller's `apply` as ONE step. Each body ends its file act in one
17	// `rescan()`, so it is called from a handler or a command — never from a
18	// `.graphicsDidChange` or `.projectGraphicsDidChange` observer (`drain()`
19	// is not re-entrant). Fonts and assets are never touched.
20	
21	import AppKit
22	import CryptoKit
23	
24	extension ProjectDocument {
25	    /// The clips drawn by the module `name`, one group per container that
26	    /// holds any: the timeline first (`nest` nil), then the nests by id; ids
27	    /// ascending. Reads the DOCUMENT, whatever nest is open.
28	    func graphicClips(named name: String) -> [(nest: UInt32?, clips: [UInt32])] {
29	        let snapshot = project.snapshot
30	        func drawn(_ clips: [ClipSnapshot]) -> [UInt32] {
31	            clips.filter { $0.graphic?.name == name }.map(\.id).sorted()
32	        }
33	        var groups: [(nest: UInt32?, clips: [UInt32])] = []
34	        let timeline = drawn(snapshot.clips)
35	        if !timeline.isEmpty { groups.append((nil, timeline)) }
36	        for nest in snapshot.nests.sorted(by: { $0.id < $1.id }) {
37	            let inside = drawn(nest.clips)
38	            if !inside.isEmpty { groups.append((nest.id, inside)) }
39	        }
40	        return groups
41	    }
42	
43	    /// `clips 4 and 9 on the timeline and clip 12 in nest 7`: one group per
44	    /// container, joined by " and " (G-27 (b)).
45	    static func graphicClipSentence(_ groups: [(nest: UInt32?, clips: [UInt32])]) -> String {
46	        groups.map { group in
47	            let ids = group.clips.map { String($0) }
48	            let listed = ids.count == 1
49	                ? "clip \(ids[0])"
50	                : "clips " + ids.dropLast().joined(separator: ", ") + " and " + ids[ids.count - 1]
51	            return listed + (group.nest.map { " in nest \($0)" } ?? " on the timeline")
52	        }.joined(separator: " and ")
53	    }
54	
55	    /// Deletes `graphics/<name>.js`, keeping its text (G-27); the kept
56	    /// revision. Refused while a clip draws the module.
57	    func deleteGraphic(named name: String) throws -> String {
58	        let store = try graphicFilesStore()
59	        guard store.module(named: name) != nil else {
60	            throw ReelCoreError(message: store.noModuleSentence(name))
61	        }
62	        let groups = graphicClips(named: name)
63	        guard groups.isEmpty else {
64	            throw ReelCoreError(
65	                message: "The graphic \"\(name)\" is still drawn by "
66	                    + Self.graphicClipSentence(groups) + Self.graphicClipAdvice)
67	        }
68	        let revision: String
69	        do {
70	            revision = try store.removeModule(named: name)
71	        } catch {
72	            throw Self.graphicFileFailure(name, "deleted", error)
73	        }
74	        store.rescan()
75	        return revision
76	    }
77	
78	    /// Renames the module `name` to `to` (G-28): the file, its kept
79	    /// revisions, and every clip that names it — `apply` is handed one
80	    /// `set_graphic {name}` per container, each addressed to its own, to
81	    /// commit as ONE undo step, and is not called when no clip names the
82	    /// module. The ids repointed, ascending. When `apply` throws, or leaves
83	    /// a clip behind, the file is moved back and the journal put back as it
84	    /// was read before the rename: a refused rename journals no pair (G-28
85	    /// (d)). A move back that fails leaves the pair, for the repair.
86	    func renameGraphic(
87	        named name: String, to: String, apply: ([ReelOp]) throws -> Void
88	    ) throws -> [UInt32] {
89	        let store = try graphicFilesStore()
90	        guard store.module(named: name) != nil else {
91	            throw ReelCoreError(message: store.noModuleSentence(name))
92	        }
93	        guard GraphicStore.isModuleName(to) else {
94	            throw ReelCoreError(message: GraphicStore.nameSentence(to))
95	        }
96	        guard !store.holdsModule(named: to) else {
97	            throw ReelCoreError(message: "graphics/\(to).js already exists")
98	        }
99	        let drawn = graphicClips(named: to)
100	        guard drawn.isEmpty else {
101	            throw ReelCoreError(
102	                message: "The name \"\(to)\" is already drawn by "
103	                    + Self.graphicClipSentence(drawn) + Self.graphicClipAdvice)
104	        }
105	        if let nest = scope {
106	            throw ReelCoreError(
107	                message: "rename_graphic has no meaning inside nest \(nest): it renames the "
108	                    + "module for every clip in the project, the timeline's included. "
109	                    + "set_scope with no arguments comes back out; then rename.")
110	        }
111	        let journalled = GraphicStore.renameJournalBytes(in: store.folderURL)
112	        do {
113	            try store.moveModule(from: name, to: to)
114	        } catch {
115	            throw Self.graphicFileFailure(name, "renamed", error)
116	        }
117	        store.rescan()
118	        let groups = graphicClips(named: name)
119	        guard !groups.isEmpty else { return [] }
120	        let ops = groups.map {
121	            ReelOp.setGraphicRaw(clips: $0.clips, patch: ["name": to]).scoped($0.nest)
122	        }
123	        func moveBack() {
124	            if (try? store.moveModule(from: to, to: name)) != nil {
125	                GraphicStore.putBackRenameJournal(journalled, in: store.folderURL)
126	            }
127	            store.rescan()
128	        }
129	        do {
130	            try apply(ops)
131	        } catch {
132	            moveBack()
133	            throw error
134	        }
135	        guard graphicClips(named: name).isEmpty else {
136	            moveBack()
137	            throw ReelCoreError(
138	                message: "graphics/\(name).js could not be renamed: its clips did not take "
139	                    + "the new name")
140	        }
141	        return groups.flatMap { $0.clips }.sorted()
142	    }
143	
144	    /// Writes a kept text of `name` back as `graphics/<name>.js` (G-29):
145	    /// `revision`, else the newest kept; the revision restored. The text it
146	    /// replaces is kept by the rescan's pass. Works when the file is absent.
147	    /// A kept file whose bytes are not the revision in its name is not a
148	    /// kept text (spec §5.6): refused, nothing written (G-29 (d)).
149	    func restoreGraphic(named name: String, revision: String?) throws -> String {
150	        let store = try graphicFilesStore()
151	        let kept = store.kept(named: name)
152	        guard var entry = kept.first else {
153	            throw ReelCoreError(
154	                message: "No kept revision of \"\(name)\" — one is kept when a write replaces "
155	                    + "a module's text or delete_graphic removes it")
156	        }
157	        if let revision = revision {
158	            guard let asked = kept.first(where: { $0.revision == revision }) else {
159	                let listed = kept.map(\.revision).joined(separator: ", ")
160	                throw ReelCoreError(
161	                    message: "\"\(name)\" has no kept revision \(revision) — kept: \(listed)")
162	            }
163	            entry = asked
164	        }
165	        do {
166	            let bytes = try Data(contentsOf: entry.url)
167	            guard GraphicStore.hex(SHA256.hash(data: bytes)) == entry.revision else {
168	                let others = kept.filter { $0 != entry }.map(\.revision)
169	                throw ReelCoreError(
170	                    message: "graphics/history/\(name)/\(entry.url.lastPathComponent) was "
171	                        + "changed outside Frame Job and no longer holds the revision in its "
172	                        + "name; it is not restored — other kept revisions: "
173	                        + (others.isEmpty ? "none" : others.joined(separator: ", ")))
174	            }
175	            try store.write(name: name, bytes: bytes)
176	        } catch let error as ReelCoreError {
177	            throw error
178	        } catch {
179	            throw Self.graphicFileFailure(name, "written", error)
180	        }
181	        store.rescan()
182	        return entry.revision
183	    }
184	
185	    /// The repair (G-28 (e)), in ONE direction: a journalled pair says the
186	    /// app last moved the file FROM its first name TO its second, and for
187	    /// each pair, newest first, when the first name is drawn by a clip, has
188	    /// no file and has no kept revision, while the second has a file and no
189	    /// clip, the file is moved back under the first — which journals the
190	    /// pair the other way round, so Redo is the same repair. One `rescan()`
191	    /// if anything moved. Never from a pair's first name to its second: a
192	    /// drawn second name with no file is a removal the app did not make
193	    /// (G-28 (f)). A file-less name WITH kept revisions is a deleted module
194	    /// (G-27 (f)) and is left alone. Returns at once when every drawn name
195	    /// has a file.
196	    func reconcileGraphicNames() {
197	        guard let store = graphicStore else { return }
198	        let snapshot = project.snapshot
199	        let drawn = Set(
