import AVFoundation
import ImageIO
import UniformTypeIdentifiers

// MARK: - Choosing a pipeline

/// What `Exporter` needs of whatever is actually writing the file.
///
/// There are two now: `ExportWriter` (`ExporterWriter.swift`), which encodes
/// a movie through `AVAssetWriter`, and `ImageSequenceWriter` below, which
/// assembles a GIF or an APNG frame by frame through ImageIO. Inside they
/// have nothing in common — one reads a composition back on AVFoundation's
/// schedule, the other renders single frames offline — but from the sheet's
/// side an export is an export: it starts once, it reports a fraction while
/// it runs, it can be cancelled, and it calls back exactly once on the main
/// thread. That is the whole protocol, and it is what lets `Exporter` keep
/// one progress timer, one `finish` and one set of `ExportError`s instead of
/// a second copy of each per format.
protocol ExportPipeline: AnyObject {
    /// 0…1, polled by `Exporter`'s timer every `Exporter.progressInterval`.
    var progress: Double { get }
    /// Begins the write. Main thread; `completion` is called exactly once, on
    /// the main thread, and may be called before this returns.
    func start(completion: @escaping (Result<URL, any Error>) -> Void)
    /// Stops as soon as the write notices. Safe from any thread, safe to call
    /// twice, and safe to call after the write has already finished.
    func cancel()
}

/// The writer already had this shape to the letter. Declaring the conformance
    /// edit for the burn-in at all.
    ///
    /// `graphics` goes the same way for the same reason: the export's pin is
    /// on the export's key, and each image frame pins it on its own.
    static func pipeline(
        built: BuiltComposition, project: ReelProject, urls: [UInt32: URL],
        settings: ExportSettings, chapters: [ExportChapter], options: RecipeOptions,
        graphics: GraphicSet?, to url: URL
    ) throws -> any ExportPipeline {
        // A WebM is the core's to write (spec §11 CX-15 (2)): the second writer.
        if settings.container.lowercased() == "webm" {
            return try ExportWebMWriter(
                built: built, settings: settings, chapters: chapters, to: url)
        }
        guard settings.isImageSequence else {
            let mix = try ExportWriter(built: built, settings: settings, chapters: chapters, to: url)
            guard !settings.stems.isEmpty, let plan = project.plan else { return mix }
            // An audio row's stems (spec §11 AU-108): each a fresh build of the
            // same plan on the export's key, beside the mix.
            let planJSON = project.planJSON
            let key = built.recipeKey
            return try ExportStemsPipeline(
                mix: mix, stems: settings.stems, settings: settings, mixURL: url,
                sources: Array(urls.values),
                rebuild: {
                    try CompositionBuilder.build(
                        plan: plan, planJSON: planJSON, urls: urls, recipeKey: key)
                })
        }
        return try ImageSequenceWriter(
            project: project, urls: urls, settings: settings, options: options,
            graphics: graphics, to: url)
    }
}

// MARK: - The two image formats

/// A format ImageIO assembles from a list of frames (spec §7.8).
///
/// Both are one `CGImageDestination` holding many images, and both keep their
/// animation properties under the destination's format dictionary — but not
/// core states as `audio: false` for both rows rather than leaving it to be
/// discovered here.
///
/// **Progress and cancellation match the writer exactly**, because the sheet
/// cannot tell which pipeline it got: the fraction is frames appended over
/// frames wanted and `Exporter`'s 0.1 s timer reads it, the cancel flag is
/// checked between frames — a single frame is bounded work, so a cancel lands
/// within one — and `completion` is called once, on the main thread.
final class ImageSequenceWriter: ExportPipeline {

    /// The most frames either format will be assembled from. A refusal rather
    /// than a truncation: a GIF that silently stopped halfway would be a file
    /// the user did not ask for, and the message names the two knobs that fix
    /// it.
    ///
    /// **What the cap protects against.** Both formats store every frame as a
    /// whole picture with no inter-frame prediction, so a file's size is
    /// frames × pixels and nothing else — the same fact that made `export.rs`
    /// pin both presets to a small size and a low rate. On top of that, every
    /// frame here is a full offline render. A ten-minute timeline exported at
    /// 30 fps is 18,000 of them: ten minutes of rendering ending in a file of
    /// hundreds of megabytes that no viewer will open, from a Range popup
    /// left on "Whole project" by mistake. 600 frames is 48 s at the GIF
    /// preset's 12.5 fps and 24 s at
    /// the APNG preset's 25 — past anything either format is used for, and
    /// short enough that the mistake is caught in the first seconds instead
        report(.success(destination))
    }

    /// Renders one frame and hands it to ImageIO. Returns the error that
    /// stopped the export, or nil when the frame is in.
    ///
    /// A frame that will not render fails the whole export rather than being
    /// skipped. Skipping would leave an animation shorter than the range with
    /// no sign of which moment went missing, and every frame that renders in
    /// the preview renders here — the two go through the same composition —
    /// so a nil is a real failure worth reporting.
    private func append(at time: Ticks) -> (any Error)? {
        let rendered = Exporter.renderFrameReported(
            project: project, urls: urls, at: time, maxWidth: Int(frameSize.width),
            options: options, graphics: graphics)
        // A graphic that failed drew its error card; the frame is not written
        // and `fail` removes the file.
        if let failure = rendered.graphics.first(where: { $0.failed }) {
            return Exporter.graphicFailed(failure)
        }
        guard let image = rendered.image else {
            let timecode = ReelTime.format(time, fps: fps, frames: true)
            return Exporter.ExportError.failed(
                "The frame at \(timecode) could not be rendered, so the "
                    + "\(format.displayName) was not written.")
        }
        let frame = format.carriesLabel ? FrameWriter.labelled(image) : image
        CGImageDestinationAddImage(sink, Self.sized(frame, to: frameSize), frameProperties)
        return nil
    }

    /// Reports a failure, having removed whatever ImageIO may already have
    /// put on disk. A half-written GIF is not a GIF, and `AVAssetWriter`'s
    /// `cancelWriting` removes its own part-file for the same reason.
    private func fail(_ error: any Error) {
        try? FileManager.default.removeItem(at: destination)
    /// The default is `.none`, so a caller that says nothing writes exactly
    /// the file it wrote before phase 7.
    ///
    /// **`graphics` is the document's compiled set as the export was asked
    /// for** (G-13, `ExporterGraphics.swift`): pinned on this export's key
    /// for its whole life, gated before the build, and the export stopped
    /// on the first frame a graphic fails. nil draws every graphic's slate.
    func export(
        project: ReelProject, urls: [UInt32: URL], settings: ExportSettings, to url: URL,
        options: RecipeOptions = .none, graphics: GraphicSet? = nil,
        progress: @escaping (Double) -> Void,
        completion: @escaping (Result<URL, any Error>) -> Void
    ) {
        setCancelRequested(false)
        setMeasureProgress(0)
        loudnessReport = nil
        graphicWarnings = []
        cursorWarnings = []
        pendingLoudness = nil
        progressHandler = progress
        completionHandler = completion
        destination = url

        guard let plan = project.plan else {
            finish(.failure(ExportError.noPlan))
            return
        }
        // An EMPTY timeline is still refused; a timeline of nothing but text,
        // shapes and images is not. Those layers own no composition track
        // (§7.2), but CompositionBuilder gives that case a placeholder video
        // track so the recipe can still drive every frame.
        guard plan.duration > 0 else {
            finish(.failure(ExportError.emptyTimeline))
            return
        }

        let key = RecipeSource.shared.register()
        recipeKey = key
        RecipeSource.shared.set(project, for: key)
        // The options belong to the KEY, not to the handle, which is what
        // makes this enough: `finish` unregisters the key and takes them with
        // it, and nothing else in the process can be reading it.
        RecipeSource.shared.setOptions(options.delivering(settings), for: key)
        if let graphics = graphics { GraphicRegistry.shared.pin(graphics, for: key) }

        measureShare = Exporter.measuresLoudness(settings)
            ? (settings.isAudioOnly ? 0.5 : 0.1) : 0
        // The timer starts BEFORE the build rather than with the writer,
        // because the measurement pass is the first thing with a fraction to
        // report and, on an audio-only export, half the wait.
        startProgressTimer()

        let planJSON = project.planJSON
        buildQueue.async { [weak self] in
            let build = {
                try CompositionBuilder.build(
                    plan: plan, planJSON: planJSON, urls: urls, recipeKey: key)
            }
            // A module that does not compile refuses the export here, through
            // `startWriting`'s `.failure` arm, before the destination is touched.
            // Every clip's cursor track is waited for first (spec §11 CU-37 (b)).
            var cursorWarnings: [ExportCursorWarning] = []
            let result = Exporter.graphicsRefusal(
                project: project, settings: settings, graphics: graphics
            ).map { Result<BuiltComposition, any Error>.failure($0) } ?? Result {
                cursorWarnings = try Exporter.waitForCursors(
                    project: project, key: key, at: nil, options: options.delivering(settings),
                    cancelled: { self?.isCancelled ?? true })
                return try Exporter.withRampAudio(plan: plan, urls: urls, settings: settings,
                    key: key, cancelled: { self?.isCancelled ?? true }, then: build) }
            // Read here, not on the main thread: the markers come off the
            // SNAPSHOT, and on a handle nothing has looked at yet that is the
            // first decode of the whole project JSON.
            let chapters = ExportChapter.list(from: project.snapshot.markers)
            var loudness: ExportLoudness?
            if case .success = result, Exporter.measuresLoudness(settings), let self = self,
                !self.isCancelled
            {
                // A composition of its own for the measurement (see the type
                // doc): the same plan, the same media, a fresh `AVAudioMix`
                // with fresh taps, and a video composition nothing reads.
                if let measured = try? build() {
                    loudness = self.measureLoudness(measured, settings: settings)
                }
            }
            DispatchQueue.main.async { [weak self] in
                self?.cursorWarnings = cursorWarnings
                self?.startWriting(
                    result, project: project, urls: urls, chapters: chapters,
                    settings: settings, loudness: loudness, graphics: graphics, to: url)
            }
        }
    }

    /// Cancels whatever stage the export is at. Safe to call twice, and safe
    /// to call before the composition has finished building — that is what
        case .success(let composition):
            built = composition
        }
        // AVFoundation refuses to write over an existing file, and a stale
        // one under a half-written image sequence would be no better. The
        // save panel already asked for permission to replace, so removing it
        // here is the user's answer being carried out, not a surprise.
        try? FileManager.default.removeItem(at: url)

        // Which pipeline writes it is the settings' decision rather than this
        // file's: `Exporter.pipeline` reads the core's `avf_preset` and hands
        // back the `AVAssetWriter` path, the WebM writer or the ImageIO one.
        //
        // The recipe options are read back off the KEY rather than carried
        // down from `export` as a second copy, so the export has exactly one
        // record of what it was asked for and the two pipelines cannot end up
        // disagreeing about it.
        let options = recipeKey.map { RecipeSource.shared.options(for: $0) } ?? .none
        let writer: any ExportPipeline
        do {
            writer = try Exporter.pipeline(
                built: built, project: project, urls: urls, settings: settings,
                chapters: chapters, options: options, graphics: graphics, to: url)
        } catch {
            finish(.failure(error))
            return
        }
        self.writer = writer
        // The gain is not part of choosing a pipeline, so it is handed over
        // after the pick rather than through it: `Exporter.pipeline` stays
        // the one place that decides WHICH pipeline writes a file, and a
        // gain only ever exists for settings that pick resolves to the
        // `AVAssetWriter` path — `measuresLoudness` refuses the image rows,
        // which are the only ones it does not.
        if let loudness = loudness, !loudness.isUnity {
            (writer as? any ExportAudioNormalizing)?.normalizeAudio(byLinearGain: Float(loudness.linearGain))
        }
        Exporter.startGraphicPrefetch(key: recipeKey, project: project, graphics: graphics,
            built: built, settings: settings, pipeline: writer)

        startProgressTimer()
        progressHandler?(measureShare)
        // The pipeline calls back on the main thread, exactly once. The bar
        // is driven to full here rather than left wherever the last sample
        // put it, so a consumer that watches only `progress` still sees the
        // end.
        writer.start { [weak self] result in
            guard let self = self else { return }
            if case .success = result { self.progressHandler?(1) }
            self.finish(Exporter.encoderOutcome(result, settings: settings, destination: url))
        }
    }

    /// The documented progress-timer seam (app/CLAUDE.md). A run-loop timer,
    /// not a dispatch source, so it stops deterministically the moment the
    /// write finishes. Idempotent: `export` starts it for the measurement
    /// and `startWriting` for the write, and only one runs.
    private func startProgressTimer() {
        guard timer == nil else { return }
        timer = Timer.scheduledTimer(
            withTimeInterval: Exporter.progressInterval, repeats: true
        ) { [weak self] _ in
            self?.pollProgress()
        }
    }

    private func pollProgress() {
        // A graphic failed on the render thread: stop the write, and `finish`
        // says which graphic and which frame.
        if let key = recipeKey, GraphicRegistry.shared.failure(for: key) != nil { cancel() }
        progressHandler?(currentProgress)
    }

    /// The bar: the measurement's share first, the write's the rest of the
    /// way. `measureShare` is 0 for a format with no sound, so an export
    /// that measures nothing reports exactly what it reported before.
    private var currentProgress: Double {
        if let writer = writer {
            return measureShare + writer.progress * (1 - measureShare)
        }
        lock.lock()
        defer { lock.unlock() }
        return measureProgress * measureShare
    }

    /// What the sheet should say while this runs, or nil for its own
    /// wording. Only the measurement has a phase of its own: the build
    /// before it is "Preparing…" and everything after it is "Writing…",
    /// which is what the sheet already says. `measuring` is set only once
    /// the reader has started, so the label appears exactly while samples
    /// are being measured and not for the build that precedes them.
    var phaseDescription: String? {
        lock.lock()
        defer { lock.unlock() }
        return measuring ? "Measuring loudness…" : nil
    }

    /// The one exit. Tears down the timer and the recipe slot before the
    /// caller hears anything, so a completion handler that starts another
    /// export finds this one fully unwound. The measurement is PUBLISHED
    /// here rather than cleared: both callers read it after their completion
    /// has fired.
    private func finish(_ result: Result<URL, any Error>) {
        let result = Exporter.graphicOutcome(result, key: recipeKey, destination: destination)
        loudnessReport = pendingLoudness
        graphicWarnings = Exporter.graphicWarnings(on: recipeKey)
        pendingLoudness = nil
        timer?.invalidate()
        timer = nil
        releaseRecipeKey()
        writer = nil
        let completion = completionHandler
        completionHandler = nil
        progressHandler = nil
        completion?(result)
    }

    /// For `finish` and `deinit`; `deinit` defers `ramp`, as it can run in `RampAudioRenders.wait`.
    private func releaseRecipeKey(ramp: (@escaping () -> Void) -> Void = { $0() }) {
        guard let key = recipeKey else { return }
        RecipeSource.shared.unregister(key)
        GraphicPrefetch.shared.stop(key)
        GraphicRegistry.shared.unpin(key)
        ramp {
            RampAudioRenders.shared.release(owner: key)
            Exporter.releaseMasks(key: key)
        }
        recipeKey = nil
    }

    // MARK: - Shared state

        /// What this export asks of the PICTURE besides the timeline — the
        /// burn-in (`RecipeOptions`). Carried per job, because two jobs from
        /// one document may legitimately differ in it.
        let options: RecipeOptions
        /// The document's compiled graphics as they stood AT ENQUEUE (G-13) —
        /// the type doc's list again: a module saved after Add to Queue is not
        /// in the handle, and the document's set is swapped by that save and
        /// dropped when it closes. `Exporter.export` pins it for the write.
        let graphics: GraphicSet?
        var state: State = .waiting
        /// 0…1, and only meaningful while `state` is `.running`.
        var progress: Double = 0
        /// The line a person reads when it is over: what was written and what
        /// the file measured, or why it stopped — plus the one thing worth
        /// saying mid-flight, that a cancel is in hand. While it waits, the
        /// ledger's sentence when the memory limit holds it (CX-18), else nil.
        var message: String?
        /// What the exporter says it is doing right now, or nil for "writing",
        /// which is the caller's own wording. Today the only phase is the
        /// loudness measurement, which on an audio-only export is half the wait
        /// and the half where nothing is on disk yet.
        ///
        /// A field of its own rather than a use of `message`, because the two
        /// are written by different things at the same time: the progress tick
        /// arrives ten times a second and would otherwise wipe the "Stopping…"
        /// a person had just asked for.
        var phase: String?
        /// Set on a COMPLETED job when a later job starts writing to the same
        /// path, because from that moment this row's file is not this row's
        /// any more — `Exporter.startWriting` removes whatever is at the
        /// destination before it builds its pipeline, so the earlier export is
        /// gone whether the later one succeeds, fails or is cancelled.
        ///
        /// The row stops claiming "Exported …" and stops offering Show in
        /// Finder. It is a fact about what happened rather than a state: the
        /// job really did complete, and rewriting its `state` would lose that.
        ///
        /// One case marks it where the file in fact survives, and it is the
        /// honest direction of the two: a later job whose COMPOSITION fails to
        /// build returns before the delete, so nothing was destroyed. It is
        /// left alone rather than reached for, because knowing which failures
        /// precede the delete means reading `Exporter`'s stages from here, and
        /// a shared destination implies a shared project — a build that failed
        /// for job 2 would almost always have failed for job 1.
        var superseded: Bool = false
        /// What the graphics warned while a COMPLETED job's file was drawn
        /// (G-24 (c)): the row's count and its tooltip's list.
        var graphicWarnings: [ExportGraphicWarning] = []
        var cursorWarnings: [ExportCursorWarning] = []  // spec §11 CU-37 (c)
        /// What a COMPLETED job's sound measured, read off its exporter at the
        /// finish — the figures the row's message summarises, kept whole for
    /// but it no longer pretends the person was warned.** The reason first
    /// given here was that "the save panel asked about replacing an existing
    /// file both times", and that is false in exactly the case that matters:
    /// `NSSavePanel` prompts only when something is at the path as Save is
    /// confirmed, and job 1 spends its build and its whole loudness
    /// measurement pass with nothing at the destination — `Exporter.export`
    /// does both before `startWriting` deletes and `AVAssetWriter` creates —
    /// so two Add to Queue actions in quick succession are never asked
    /// anything. Refusing here would still be wrong: overwriting your own
    /// export is a thing a person is allowed to do, and the queue must not be
    /// the one place in the app where they may not. What was wrong was the
    /// silence AFTERWARDS, and `launch` is where that is answered — the
    /// earlier row is marked `superseded` the moment a later job starts
    /// writing to its path, so no row goes on offering a file that another
    /// job has since deleted or replaced.
    @discardableResult
    func enqueue(
        project: ReelProject, urls: [UInt32: URL], settings: ExportSettings, to url: URL,
        options: RecipeOptions = .none, graphics: GraphicSet? = nil
    ) -> UInt64 {
        let id = nextID
        nextID += 1
        jobs.append(
            Job(
                id: id, project: project, urls: urls,
                // The third piece of the enqueue-time snapshot; the type doc
                // says why it cannot be left to be asked again at run time.
                reverse: ReverseSource.shared.resolution(publishedFor: project),
                settings: settings, destination: url, options: options, graphics: graphics))
        didChange()
        start()
        return id
    }

    // MARK: - Running

    /// Runs the first waiting job the encoder ledger admits, if nothing is
    /// running already — passing over a held one (CX-18 (7)). Idempotent
    /// and safe to call at any time: `enqueue` calls it, every completion
    /// calls it, the ledger's change calls it, and a caller may call it itself.
    ///
    /// The loop is for the synchronous-refusal case `isLaunching` describes: a
    /// job the exporter refuses without ever going asynchronous has already
    /// finished by the time `launch` returns, and this frame takes the next
    /// one rather than recursing into it.
    func start() {
        guard !isLaunching else { return }
        isLaunching = true
        defer { isLaunching = false }
        while exporter == nil, let index = jobs.firstIndex(where: {
            $0.state == .waiting && ledger.admits($0.settings)
        }) {
            launch(at: index)
        }
        noteHeld()
    }

    /// Every waiting encoder job's `message` set to why it is held, or cleared when it is
    /// not — leaving out this queue's own running booking, which it waits behind anyway.
    private func noteHeld() {
        var changed = false
        for index in jobs.indices
        where jobs[index].state == .waiting && jobs[index].settings.writer != nil {
            let sentence = ledger.waitingSentence(for: jobs[index].settings, ignoring: ledgerToken)
            if jobs[index].message != sentence {
                jobs[index].message = sentence
                changed = true
            }
        }
        if changed { didChange() }
    }

    /// One job handed to one fresh `Exporter`. The exporter is stored BEFORE
    /// the call, because an early refusal calls back before `export` returns
    /// and `finished` has to find it there.
    private func launch(at index: Int) {
        let job = jobs[index]
        jobs[index].state = .running
        jobs[index].progress = 0
        jobs[index].message = nil
        jobs[index].phase = nil
        // Any COMPLETED row naming this same path stops claiming its file
        // here, and here rather than when the file is actually deleted: the
        // delete happens inside `Exporter.startWriting`, seconds later and in
        // a file this one may not reach into, and being early is the honest
        // direction — a row that stops offering a file just before it is
        // destroyed costs a person nothing, where one that offers it just
        // after sends them to the Finder for something that is gone.
        for other in jobs.indices
        where other != index && jobs[other].state == .completed
            && jobs[other].destination == job.destination
        {
            jobs[other].superseded = true
        }
        // The job's own reverse resolution, held against its own handle for
        // exactly the length of this write. At most one pin exists at a time,
        // which is the invariant `ReverseSource.pin` asks its callers for and
        // which this class keeps for free by running one job at a time.
        ReverseSource.shared.pin(job.reverse, for: job.project)
        pinnedProject = job.project
        // Booked BEFORE `export`, whose early refusals finish synchronously inside it.
        ledgerToken = ledger.begin(job.settings)
        let exporter = Exporter()
        self.exporter = exporter
        didChange()
        exporter.export(
            project: job.project, urls: job.urls, settings: job.settings, to: job.destination,
            options: job.options, graphics: job.graphics,
            progress: { [weak self] value in self?.progressed(job.id, value) },
            completion: { [weak self] result in self?.finished(job.id, result) })
    }

    private func progressed(_ id: UInt64, _ value: Double) {
        guard let index = jobs.firstIndex(where: { $0.id == id }),
            jobs[index].state == .running
        else { return }
        jobs[index].progress = min(max(value, 0), 1)
        // The exporter names its own phase while it has one. The progress
        // sheet asks the same question with the same call; a row that said
        // "Writing" through the measurement would be claiming a file that does
        // not exist yet.
        jobs[index].phase = exporter?.phaseDescription
        didChange()
    }

    /// The one exit for all three outcomes, and the mirror of
    /// `ExportProgressSheetController.finished` — deliberately, because there
    /// must not be two accounts of what finishing an export means. The
    /// exporter is cleared first, so the `start()` at the foot can hand the
